package com.primehr.security;
import com.primehr.integration.administrative.*; import org.junit.jupiter.api.Test; import org.springframework.security.access.AccessDeniedException; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class SuccessionPlanningPermissionGuardTest {
 private static EffectiveFeaturePermission permission(String key,boolean publish,boolean approve,PermissionDataScope scope){return new EffectiveFeaturePermission(key,false,true,true,true,true,publish,true,approve,false,false,true,scope);}
 @Test void careerPathsRequireAgencyWideScope(){var client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.CAREER_PATH,true,false,PermissionDataScope.ASSIGNED_RECORDS));var guard=new SuccessionPlanningPermissionGuard(client);assertThatThrownBy(()->guard.require(SuccessionPlanningPermissionGuard.CAREER_PATH,PrimeHrAction.ACCESS,"Bearer t")).isInstanceOf(AccessDeniedException.class);}
 @Test void criticalPositionApprovalAllowsAssignedScopeWithApproveGrant(){var client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,false,true,PermissionDataScope.ASSIGNED_RECORDS));var guard=new SuccessionPlanningPermissionGuard(client);assertThat(guard.require(SuccessionPlanningPermissionGuard.CRITICAL_POSITION,PrimeHrAction.APPROVE,"Bearer t")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);}
 @Test void candidatePoolPreservesOwnRecordsScope(){var client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.POOL,false,false,PermissionDataScope.OWN_RECORDS));var guard=new SuccessionPlanningPermissionGuard(client);assertThat(guard.require(SuccessionPlanningPermissionGuard.POOL,PrimeHrAction.ADD,"Bearer t")).isEqualTo(PermissionDataScope.OWN_RECORDS);}
 @Test void readinessPreservesAssignedScopeAndFinalizeGrant(){var client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(new EffectiveFeaturePermission(SuccessionPlanningPermissionGuard.READINESS,false,true,true,true,true,false,true,true,true,false,true,PermissionDataScope.ASSIGNED_RECORDS));var guard=new SuccessionPlanningPermissionGuard(client);assertThat(guard.require(SuccessionPlanningPermissionGuard.READINESS,PrimeHrAction.FINALIZE,"Bearer t")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);}
 @Test void developmentPreservesOwnScopeForCandidateAccess(){var client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.DEVELOPMENT,false,false,PermissionDataScope.OWN_RECORDS));var guard=new SuccessionPlanningPermissionGuard(client);assertThat(guard.require(SuccessionPlanningPermissionGuard.DEVELOPMENT,PrimeHrAction.ACCESS,"Bearer t")).isEqualTo(PermissionDataScope.OWN_RECORDS);}
 @Test void continuityRejectsOwnScopeAndAllowsAssignedApproval(){var client=mock(AdministrativeAuthorizationClient.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.CONTINUITY,false,true,PermissionDataScope.OWN_RECORDS));var guard=new SuccessionPlanningPermissionGuard(client);assertThatThrownBy(()->guard.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.APPROVE,"Bearer t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.CONTINUITY,false,true,PermissionDataScope.ASSIGNED_RECORDS));assertThat(guard.require(SuccessionPlanningPermissionGuard.CONTINUITY,PrimeHrAction.APPROVE,"Bearer t")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);}
 @Test void analyticsRequiresAgencyWideWhileReportsPreserveOwnScope(){var client=mock(AdministrativeAuthorizationClient.class);var guard=new SuccessionPlanningPermissionGuard(client);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.ANALYTICS,false,false,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(SuccessionPlanningPermissionGuard.ANALYTICS,PrimeHrAction.ACCESS,"Bearer t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(anyString(),anyString())).thenReturn(permission(SuccessionPlanningPermissionGuard.REPORT,false,false,PermissionDataScope.OWN_RECORDS));assertThat(guard.require(SuccessionPlanningPermissionGuard.REPORT,PrimeHrAction.ACCESS,"Bearer t")).isEqualTo(PermissionDataScope.OWN_RECORDS);}
}
